code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    squares = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color for rr in range(r, r + 3) for cc in range(c, c + 3)):
                # Avoid treating a subwindow of a larger solid block as another object.
                if not any((r - 1 <= sr <= r and c - 1 <= sc <= c and (sr, sc) != (r, c)) for sr, sc, _ in squares):
                    squares.append((r, c, color))
    out = [row[:] for row in grid]
    lines = []
    for r, c, color in squares:
        lines.append((r + 1, None, color))
        lines.append((None, c + 1, color))
        for x in range(w):
            if out[r + 1][x] == 0:
                out[r + 1][x] = color
        for y in range(h):
            if out[y][c + 1] == 0:
                out[y][c + 1] = color
    # Where lines of distinct objects cross, the crossing remains empty.
    for i, (row, col, color) in enumerate(lines):
        if row is None:
            continue
        for other_row, other_col, other_color in lines:
            if other_col is not None and other_color != color:
                out[row][other_col] = 0
    return out
'''
